export function findFeatureRegistryById(id: string): FeatureRegistryRecord | undefined {
  return FEATURE_REGISTRY_DATABASE.find(item => item.id === id);
}

export function getAllFeatureRegistryRecords(): FeatureRegistryRecord[] {
  return FEATURE_REGISTRY_DATABASE;
}

export function filterFeatureRegistryByPredicate(predicate: (item: FeatureRegistryRecord) => boolean): FeatureRegistryRecord[] {
  return FEATURE_REGISTRY_DATABASE.filter(predicate);
}

export function countFeatureRegistryRecords(): number {
  return FEATURE_REGISTRY_DATABASE.length;
}
